```rust
use std::fs;
use std::io;
use std::process;
use std::env;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() != 2 {
        eprintln!("Usage: {} <filename>", args[[0]]);
        process::exit(1);
    }

    let filename = &args[1];
    let urls = read_urls_from_file(filename);

    let youtube_urls: Vec<String> = urls.into_iter(|url| {
        if url.starts("https://www.youtube.com/") {
            Some(url)
        } else {
            None
        }
    }).collect();

    for url in youtube_urls {
        download_youtube(url);
    }
}

fn read_urls_from_file(filename: &str) -> Vec<String> {
    let contents = fs::read_to_string(filename).expect("Failed to read file");

    contents.lines().map(|line| line.to_string()).collect()
}

fn download_youtube(url: String) {
    let output = process::Command::new("yt-dlp")
        .arg(url)
        .output().expect("Failed to execute yt-dlp");

    if output.status.success() {
        println!("Downloaded: {}", url);
    } else {
        eprintln!("Failed to download: {}", url);
    }
}
```

