use std::collections::HashSet;

fn primes() -> impl Iterator<Item = u32> {
    let mut primes = HashSet::new();
    let mut num = 2;

    std::iter::from_fn(move || {
        if primes.iter().any(|&p| num % p == 0) {
            num += 1;
        } else {
            primes.insert(num);
            num += 1;
        }
        Some(num - 1)
    })
}

fn main() {
    for prime in primes().take(10) {
        println!("{}", prime);
    }
}
```

