        front = (front - 1 + array.length) % array.length;
        array[front] = elem;
        size++;
        modCount++;
    }
}

public void pushLast(E elem) {
    synchronized (this) {
        expandIfNeeded();
        array[rear] = elem;
        rear = (rear + 1) % array.length;
        size++;
        modCount++;
    }
}

public E popFirst() {
    synchronized (this) {
        if (isEmpty()) throw new NoSuchElementException();
        E elem = array[front];
        array[front] = null; // Allow GC to work
        front = (front + 1) % array.length;
        size--;
        modCount++;
        shrinkIfNeeded();
        return elem;
    }
}

public E popLast() {
    synchronized (this) {
        if (isEmpty()) throw new NoSuchElementException();
        rear = (rear - 1 + array.length) % array.length;
        E elem = array[rear];
        array[rear] = null; // Allow GC to work
        size--;
        modCount++;
        shrinkIfNeeded();
        return elem;
    }
}

public E first() {
    synchronized (this) {
        if (isEmpty()) throw new NoSuchElementException();
        return array[front];
    }
}

public E last() {
    synchronized (this) {
        if (isEmpty()) throw new NoSuchElementException();
        return array[(rear - 1 + array.length) % array.length];
    }
}

public boolean isEmpty() {
    synchronized (this) {
        return size == 0;
    }
}

public int size() {
    synchronized (this) {
        return size;
    }
}

public void clear() {
    synchronized (this) {
        Arrays.fill(array, null);
        front = 0;
        rear = 0;
        size = 0;
        modCount++;
    }
}

public Iterator<E> iterator() {
    synchronized (this) {
        return new DeQueueIterator(front, 1);
    }
}

public Iterator<E> descendingIterator() {
    synchronized (this) {
        return new DeQueueIterator((rear - 1 + array.length) % array.length, -1);
    }
}
```

By adding the `synchronized` keyword to the methods, you ensure that only one thread can access the critical sections at a time, preventing any non-atomic operations on the 'modCount' field.<|im_end|>

