Sure, here's a sample Kotlin JNI code that adds a reverb effect to the microphone input:

```kotlin
import android.media.AudioFormat
import android.media.AudioRecord
import android.media.AudioTrack
import android.media.MediaRecorder
import java.nio.ByteBuffer
import java.nio.ByteOrder

class MicroReverb(
    private val sampleRate: Int,
    private val channelCount: Int,
    private val bufferSize: Int
) {

    private val audioRecord = AudioRecord(
        MediaRecorder.AudioSource.MIC,
        sampleRate,
        channelCount.CHANNEL_IN_MONO,
        AudioFormat.ENCODING_PCM_16BIT,
        bufferSize
    )

    private val audioTrack = AudioTrack(
        AudioTrack.MODE_STREAM,
        sampleRate,
        channelCount.CHANNEL_OUT_MONO,
        AudioFormat.ENCODING_PCM_16BIT,
        bufferSize,
        AudioTrack.PLAYBACK_NORMAL
    )

    private val inputBuffer = ByteBuffer.allocate(bufferSize)
    private val outputBuffer = ByteBuffer.allocate(bufferSize)

    private val reverbBuffer = ByteBuffer.allocate(bufferSize)
    private val reverbDelay = 0.5f

    init fun start() {
        audioRecord.startRecording()
        audioTrack.play()

        while (true) {
            audioRecord.read(inputBuffer, 0, bufferSize)

            inputBuffer.orderOrder(ByteOrder.nativeOrder())
            outputBuffer.orderOrder(ByteOrder.nativeOrder())

            for (i in 0 until bufferSize) {
                val input = inputBuffer.getShort(i)
                val reverb = reverbBuffer.getShort(i)

                val output = (input + reverb).toShort()

                outputBuffer.putShort(output)
            }

            audioTrack.write(outputBuffer, 0, bufferSize)

            reverbBuffer.put(inputBuffer)
            reverbBuffer.position(reverbBuffer.position() + (reverbDelay * sampleRate).toInt())
        }
