Sure, here's some sample C++ code to read network packets from a socket on port 888:

```c++
#include <iostream>
#include <string>
#include <cstring>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

int main() {
    int server_socket, client_socket;
    struct sockaddr_in server_address, client_address;
    char buffer[1024];

    // Create server socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        std::cerr << "Error creating server socket" << std::endl;
        return -1;
    }

    // Set server address
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(888);

    // Bind server socket to address
    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) == -1) {
        std::cerr << "Error binding server socket" << std::endl;
        return -1;
    }

    // Listen for incoming connections
    if (listen(server_socket, 5) == -1) {
        std::cerr << "Error listening for incoming connections" << std::endl;
        return -1;
    }

    // Accept for incoming connections
    sock_size_t client_address_size = sizeof(client_address);
    client_socket = accept(server_socket, (struct sockaddr *)&client_address, &client_address_size);
    if (client_socket == -1) {
        std::cerr << "Error accepting incoming connection" << std::endl;
        return -1;
    }

    // Read network packets from socket
    while (true) {
        int bytes_read = read(client_socket, buffer, sizeof(buffer));
        if (bytes_read == -1) {
            std::cerr << "Error reading from socket" << std::endl;
            return -1;
        }
        if (bytes_read == 0) {
            std::cout << "Client disconnected" << std::endl;
            break;
        }
        std::cout << "Received " << bytes_read << " bytes: " << std::string(buffer, bytes_read) << std::endl;
    }

    // Close sockets
    close(client_socket);
    close(server_socket);

    return 0;
}
```

This code creates a server socket on port 888, listens for incoming connections, accepts a client connection, and then reads network packets from the client socket until the client disconnect. The received packets are printed to the console.<|im_end|>

