Sure, here's a simple implementation of an RNN using Typescript:

```typescript
class RNN {
  private input: number;
  private hidden: number;
  private output: number;
  private weights: number[];
  private bias: number;
  private learningRate: number;

  constructor(input: number, hidden: number, output: number, learningRate: number) {
    this.input = input;
    this.hidden = hidden;
    this.output = output;
    this.learningRate = learningRate;
    this.weights = [];
    this.bias = 0;

    // Initialize weights
    for (let i = 0; i < input * hidden; i++) {
      this.weights.push(Math.random() * 2 - 1);
    }
    for (let i = 0; i < hidden * output; i++) {
      this.weights.push(Math.random() * 2 - 1);
    }
  }

  public train(inputs: number[], expectedOutput: number) {
    let hiddenOutput = 0;
    let output = 0;

    // Forward pass
    for (let i = 0; i < this.input; i++) {
      hiddenOutput += inputs[i] * this.weights[i];
    }
    hiddenOutput = this.sigmoid(hiddenOutput + this.bias);
    for (let i = 0; i < this.hidden; i++) {
      output += hiddenOutput * this.weights[this.input + i];
    }
    output = this.sigmoid(output + this.bias);

    // Backward
    const error = expectedOutput - output;
    const deltaOutput = error * output * (1 - output);
    const deltaHidden = deltaOutput * this.weights[this.input];
    this.bias += this.learningRate * deltaHidden;
    for (let i = 0; i < this.input; i++) {
      this.weights[i] += this.learningRate * deltaHidden * inputs[i];
    }
    for (let i = 0; i < this.hidden; i++) {
      this.weights[this.input + i] += this.learningRate * deltaOutput * hiddenOutput;
    }
  }

  public predict(inputs: number[]): number {
    let hiddenOutput = 0;
    let output = 0;

    // Forward pass
    for (let i = 0; i < this.input; i++) {
      hiddenOutput += inputs[i] * this.weights[i];
    }
    hiddenOutput = this.sigmoid(hiddenOutput + this.bias);
    for (let i = 0; i < this.hidden; i++) {
      output += hiddenOutput * this.weights[this.input + i];
    }
    output = this.sigmoid(output + this.bias);

    return output;
  }

  private sigmoid(x: number): number {
    return 1 / (1 + Math.exp(-x));
  }
}
```

This implementation uses the sigmoid activation function and backpropagation for training. The `train` method takes an array of inputs and the expected output, and updates the weights and bias based on the error. The `predict` method takes an array of inputs and returns the predicted output.<|im_end|>

